import json,glob,re
def lab(w):
    w=re.split(r'[;,(—–]| and | then ',w)[0].strip()
    w=re.sub(r'^(The|His|Her|At|In|On|Aboard|From)\s+','',w)
    if len(w)>24: w=w[:24].rsplit(' ',1)[0]
    return w
out={}
for f in sorted(glob.glob('ch-*.json')):
    cid=f[3:-5]; c=json.load(open(f))
    for e in c['eyes']:
        out[f"{cid}:{e['id']}"]={"lat":e['lat'],"lon":e['lon'],"label":lab(e.get('where','')),"waypoints":e.get('waypoints') or []}
